  Lemma smA_dec4 : forall d0 s1 s2 out o0 s1a d1 o1 s2a d2 o2 s1b d3 o3 s2b d4 mm (junk : list byte) (P : Z)
                          (xra a2 a4 s5 s6 s7 s10 t3 t4 t5 t6 : word),
    decode_sym d false s1 d0 = Ok (o0, s1a, d1) -> decode_sym d false s2 d1 = Ok (o1, s2a, d2) ->
    decode_sym d false s1a d2 = Ok (o2, s1b, d3) -> decode_sym d false s2a d3 = Ok (o3, s2b, d4) ->
    0 <= bd_bits d0 <= 64 -> 0 <= bd_cont d0 < 2^64 -> zlen out + 4 <= dcap ->
    u8arr asegs mm DST (map (Z_to_bv 8) out ++ junk) -> zlen junk = dcap - zlen out ->
    munch [(DST, DST + dcap)] m0 mm -> wmono asegs m0 mm -> mem_inv asegs mm ->
    (forall m2 (junk2 : list byte) (y1 y12 y21 y22 y23 y26 y28 y29 y30 y31 : word),
       u8arr asegs m2 DST (map (Z_to_bv 8) (out ++ [o0; o1; o2; o3]) ++ junk2) -> zlen junk2 = dcap - zlen (out ++ [o0; o1; o2; o3]) ->
       munch [(DST, DST + dcap)] m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 ->
       evtF asegs RNG Q (STD 0x96864 m2 y1 (Z_to_bv 64 (bd_cont d0)) (Z_to_bv 64 (bd_bits d4)) (Z_to_bv 64 s2b) (Z_to_bv 64 P)
                           (Z_to_bv 64 (DST + zlen out + 4)) y12 (Z_to_bv 64 s1b) a4 (Z_to_bv 64 (DST + zlen out + 4))
                           y21 y22 y23 y26 y28 y29 y30 y31)) ->
    evtF asegs RNG Q (STD 0x965f8 mm xra (Z_to_bv 64 (bd_cont d0)) (Z_to_bv 64 (bd_bits d0)) (Z_to_bv 64 s2) (Z_to_bv 64 P)
                         (Z_to_bv 64 (DST + zlen out)) a2 (Z_to_bv 64 s1) a4 (Z_to_bv 64 (DST + zlen out)) s5 s6 s7 s10 t3 t4 t5 t6).
Proof.
