  Ltac ldbS p k :=
    let RX := fresh "RX" in
    lazymatch goal with SRC' : bytes_at asegs ?mg S0 (map (Z_to_bv 8) bs) |- evtF _ _ _ (MS _ _ _ _ _ ?mg _) =>
      pose proof (src_rd asegs mg S0 bs (p + k) SRC' ltac:(lia)) as RX end;
    rewrite ?Z.add_assoc, ?Z.add_0_r in RX;
    zstep; cbv beta; clear RX.

