  Lemma smA_ld : forall mm (p st k : Z) (xra t1 t2 a2 a3 a4 s5 s6 s7 s10 t3 t4 t5 t6 : word),
    0 <= p -> p + 8 <= zlen bs -> (st = 0 \/ st = 1) -> 0 <= k <= dcap ->
    munch [(DST, DST + dcap)] m0 mm -> wmono asegs m0 mm -> bytes_at asegs mm S0 (map (Z_to_bv 8) bs) ->
    (forall (y12 y21 y28 y29 y30 y31 : word), (st = 0 \/ dcap - 3 <= k) ->
        evtF asegs RNG Q (STD 0x96998 mm xra (Z_to_bv 64 (le64v bs p)) t1 t2 (Z_to_bv 64 (S0 + p)) (Z_to_bv 64 (DST + k)) y12 a3 a4
                             (Z_to_bv 64 (DST + k)) y21 s6 s7 s10 y28 y29 y30 y31)) ->
    (forall (y12 y21 y28 y29 y30 y31 : word), st = 1 -> k < dcap - 3 ->
        evtF asegs RNG Q (STD 0x965f8 mm xra (Z_to_bv 64 (le64v bs p)) t1 t2 (Z_to_bv 64 (S0 + p)) (Z_to_bv 64 (DST + k)) y12 a3 a4
                             (Z_to_bv 64 (DST + k)) y21 s6 s7 s10 y28 y29 y30 y31)) ->
    evtF asegs RNG Q (STD 0x96570 mm xra (Z_to_bv 64 st) t1 t2 (Z_to_bv 64 (S0 + p)) (Z_to_bv 64 (DST + k)) a2 a3 a4
                         (Z_to_bv 64 (DST + k)) s5 s6 s7 s10 t3 t4 t5 t6).
Proof.
