  (* [comment removed for export] *)
  Definition smA_inv (m1 : amem) (out : list Z) : Prop :=
    (exists junk, u8arr asegs m1 DST (map (Z_to_bv 8) out ++ junk) /\ zlen junk = dcap - zlen out)
    /\ munch [(DST, DST + dcap)] m0 m1 /\ wmono asegs m0 m1 /\ mem_inv asegs m1.
  Definition smA_ok (x : dec) : Prop :=
    bitd_ok bs (de_bd x) /\ bd_bits (de_bd x) <= 64 /\ zlen (de_out x) <= dcap /\ Forall (fun c => 0 <= c < 256) (de_out x).
  Definition smA_okr (x : dec) : Prop :=
    bitd_ok bs (de_bd x) /\ bd_bits (de_bd x) <= 2^29 /\ zlen (de_out x) <= dcap /\ Forall (fun c => 0 <= c < 256) (de_out x).
  Definition bd_regA (d0 : bitD) : Z := if bd_zero d0 then AZEROFILLED else S0 + bd_ptr d0.

  Notation HEADST x mm xra a2 s5 s6 s7 s10 t3 t4 t5 t6 :=
    (STD 0x96528 mm xra (Z_to_bv 64 (bd_cont (de_bd x))) (Z_to_bv 64 (bd_bits (de_bd x))) (Z_to_bv 64 (de_s2 x))
         (Z_to_bv 64 (S0 + bd_ptr (de_bd x))) (Z_to_bv 64 (DST + zlen (de_out x))) a2 (Z_to_bv 64 (de_s1 x)) (Z_to_bv 64 (S0 + 8))
         (Z_to_bv 64 (DST + zlen (de_out x))) s5 s6 s7 s10 t3 t4 t5 t6).
  Notation EXITST r mm y1 y10 y11 y12 y21 y22 y23 y26 y28 y29 y30 y31 :=
    (MS (mkR y1 (Z_to_bv 64 SP1) gp tp (Z_to_bv 64 (bd_cont (de_bd r))) (Z_to_bv 64 (bd_bits (de_bd r))) (Z_to_bv 64 (de_s2 r)) x8
             (Z_to_bv 64 SP1) y10 y11 y12 (Z_to_bv 64 (de_s1 r)) (Z_to_bv 64 (S0 + 8)) (Z_to_bv 64 64) (Z_to_bv 64 135040)
             (Z_to_bv 64 (DST + zlen (de_out r))) x18 x19 (Z_to_bv 64 (bd_regA (de_bd r))) y21 y22 y23
             (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) y26 (Z_to_bv 64 2147450880) y28 y29 y30 y31)
        FR (Z_to_bv 64 0x9699c) fc None mm (seg_rom asegs)).
  Definition smA_K (r : dec) : Prop :=
    forall m2 (y1 y10 y11 y12 y21 y22 y23 y26 y28 y29 y30 y31 : word), smA_okr r -> smA_inv m2 (de_out r) ->
      evtF asegs RNG Q (EXITST r m2 y1 y10 y11 y12 y21 y22 y23 y26 y28 y29 y30 y31).

  (* [comment removed for export] *)
  Lemma smA_after : forall f out s1 s2 c b p r m1 (xra a2 a4' s5 s6 s7 s10 t3 t4 t5 t6 : word),
    (forall x' r' m1' (xra' a2' s5' s6' s7' s10' t3' t4' t5' t6' : word),
       main_loop bs d dcap false f x' = Ok r' -> smA_ok x' -> smA_inv m1' (de_out x') -> smA_K r' ->
       evtF asegs RNG Q (HEADST x' m1' xra' a2' s5' s6' s7' s10' t3' t4' t5' t6')) ->
    RF_huf_fdw_sm.ml_body dcap bs d f (mkDec out s1 s2 (mkBD c b p false)) Unfinished (mkBD c b p false) = Ok r ->
    bitd_ok bs (mkBD c b p false) -> b <= 64 -> zlen out < dcap - 3 -> Forall (fun c => 0 <= c < 256) out ->
    smA_inv m1 out -> smA_K r -> a4' = Z_to_bv 64 (S0 + 8) ->
    evtF asegs RNG Q (STD 0x965f8 m1 xra (Z_to_bv 64 c) (Z_to_bv 64 b) (Z_to_bv 64 s2) (Z_to_bv 64 (S0 + p))
                         (Z_to_bv 64 (DST + zlen out)) a2 (Z_to_bv 64 s1) a4' (Z_to_bv 64 (DST + zlen out)) s5 s6 s7 s10 t3 t4 t5 t6).
